mapper.select:
select d.id, d.name, d.category_id, d.price, d.image, d.description, d.status, d.update_time, c.name as categoryName from dish as d left join category c on c.id = d.category_id

        and d.status=#{status}
        and d.name like concat('%',#{name},'%')
        and d.category_id=#{categoryId}

order by update_time desc
